function copyToClipboard(text, itemName) {
    var textarea = document.createElement("textarea");
    textarea.value = text;
    textarea.style.position = "fixed";  // Verhindert das Scrollen der Seite
    textarea.style.opacity = "0";
    document.body.appendChild(textarea);
    textarea.select();
    try {
 var successful = document.execCommand('copy');
 if (successful) {
 layer.msg(itemName + ' wurde in die Zwischenablage kopiert', { icon: 1 });
        } else {
 layer.msg('Kopieren fehlgeschlagen, bitte manuell kopieren', { icon: 2 });
 }
    } catch (err) {
 layer.msg('Kopieren fehlgeschlagen, Ihr Browser unterstützt dies nicht', { icon: 2 });
    }
    document.body.removeChild(textarea);
}

